insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level, question, options, correct_index, explanation, topic, is_general, semester, units)
values
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'According to the definition used in the lecture notes, an equation is called ''linear'' if:', '["Each term has degree one in the unknowns", "It contains at least one squared term", "It has exactly two unknowns", "It cannot be solved algebraically"]'::jsonb, 0, 'The notes define equation (1) as linear "because each term has degree one in the variables x1, x2, ..., xn" -- no unknown is raised to a power other than 1, multiplied by another unknown, or placed inside a transcendental function. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'Linear Equations', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following equations, in the notation of the lecture notes, is linear?', '["$x_1 + 2x_1x_2 + 3x_3 = 4$", "$3x_1 - x_2 = x_3 + 1$", "$3x_1^{-1} + \\sin x_2 = 0$", "$x_1^{1/2} + 3x_2 = 4$"]'::jsonb, 1, '$3x_1 - x_2 = x_3 + 1$ rearranges to $3x_1 - x_2 - x_3 = 1$, with every term of degree one in the unknowns. The others fail: the first has a product $x_1x_2$, the third has $x_1^{-1}$ and $\sin x_2$, and the fourth has $x_1^{1/2}$ -- none of degree one. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'Linear Equations', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the equation $x_1 + 2x_1x_2 + 3x_3 = 4$ linear?', '["Yes, because every coefficient is a whole number", "No, because the term $2x_1x_2$ has degree two (a product of two unknowns)", "Yes, because it has exactly 3 unknowns", "No, because it contains the number 4"]'::jsonb, 1, '$x_1x_2$ is a product of two distinct unknowns, giving that term degree two, so the equation is not linear -- exactly the first item the notes'' own exercise asks students to check. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'Linear Equations', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Is the equation $3x_1^{-1} + \sin x_2 = 0$ linear?', '["Yes", "No -- it contains $x_1^{-1}$ (a negative power) and $\\sin x_2$ (a transcendental function), neither of which is degree one", "Yes, because it equals zero", "No, because it has no constant term"]'::jsonb, 1, 'A linear equation''s terms must each be a constant times a single unknown to the first power. $x_1^{-1}$ and $\sin x_2$ both violate this, so the equation is not linear. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'Linear Equations', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In the general linear equation $a_1x_1 + a_2x_2 + \cdots + a_nx_n = b$, what is a ''solution'' to the equation?', '["Any sequence $s_1, s_2, \\ldots, s_n$ of numbers such that substituting $x_i = s_i$ satisfies the equation", "Any single number that makes $b$ equal to zero", "The coefficients $a_1, \\ldots, a_n$ themselves", "A graph of the equation"]'::jsonb, 0, 'The notes define a solution as "any sequence $s_1, s_2, \ldots, s_n$ of numbers such that the substitution $x_1=s_1, x_2=s_2, \ldots, x_n=s_n$ satisfies the equation." [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'Linear Equations', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In an $(m \times n)$ system of linear equations, what do $m$ and $n$ represent?', '["$m$ is the number of equations, $n$ is the number of unknowns", "$m$ is the number of unknowns, $n$ is the number of equations", "Both $m$ and $n$ count the number of unknowns", "Both $m$ and $n$ count the number of equations"]'::jsonb, 0, 'The notes describe "an $(m\times n)$ system of linear equation" as "the system of $m$ linear equations in $n$ unknown" -- so $m$ is the equation count and $n$ is the unknown count. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'General Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In the coefficient notation $a_{32}$ used for a system of linear equations, what does this entry represent?', '["The coefficient of $x_2$ in the third equation", "The coefficient of $x_3$ in the second equation", "The constant term of the third equation", "The third unknown itself"]'::jsonb, 0, 'The notes explain that the double-subscript notation gives each coefficient an "address": $a_{32}$ "appears in the third equation as the coefficient of $x_2$" -- first subscript = equation number, second = unknown number. [Source: Ch.1, p.2 (“Introduction” / “General Linear Systems”)]', 'General Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Two systems of linear equations are called ''equivalent'' if:', '["They have the same number of equations", "They have the same set of solutions", "They use the same variable names", "They were written by the same person"]'::jsonb, 1, 'The notes'' definition is explicit: "Two systems of linear equations are said to be equivalent if they have same set of solutions." [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'General Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Which of the following is listed in the lecture notes as one of the three ''elementary operations'' that transform a system of linear equations into an equivalent one?', '["Squaring an equation", "Interchange of two equations", "Deleting a variable from every equation", "Taking the square root of the constant term"]'::jsonb, 1, 'Theorem 1 lists exactly three elementary operations: (1) interchange of two equations, (2) multiplication of an equation by a non-zero scalar, (3) addition of a constant multiple of one equation to another -- each produces an equivalent system. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'General Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In the notation $E_i + KE_j$ used for elementary operations, what does this instruction mean?', '["Add $K$ times the $j$th equation to the $i$th equation", "Multiply the $i$th equation by $K$ and delete the $j$th", "Interchange equations $i$ and $j$, then multiply by $K$", "Subtract equation $i$ from equation $j$"]'::jsonb, 0, 'The notes'' own notation table states: "$E_i + KE_j$ -- Add $k$ times $j$th equation to the $i$th equation." [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'General Linear Systems', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using Gaussian elimination, solve the system:\n$x1 - x2 + x3 = 2$,\n$ 2x1 + x2 + 3x3 = 1$,\n$ 3x1 - x2 - 2x3 = -5$.', '["$x_1=-19/17, x_2=-26/17, x_3=27/17$", "$x_1=-2/17, x_2=-26/17, x_3=27/17$", "$x_1=-19/17, x_2=-43/17, x_3=44/17$", "$x_1=-26/17, x_2=-19/17, x_3=27/17$"]'::jsonb, 0, 'Reducing the augmented matrix to triangular (echelon) form and back-solving gives $x_3=27/17$ from the last row, then $x_2=-26/17$ and $x_1=-19/17$ from the equations above it, exactly the procedure demonstrated in Examples 3-5. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using Gaussian elimination, solve the system:\n$x1 + 2x2 - x3 = 3$,\n$ 3x1 + x2 + 2x3 = 5$,\n$ 2x1 - x2 + x3 = 4$.', '["$x_1=12/5, x_2=-1/5, x_3=-1$", "$x_1=17/5, x_2=-1/5, x_3=-1$", "$x_1=12/5, x_2=-6/5, x_3=0$", "$x_1=-1/5, x_2=12/5, x_3=-1$"]'::jsonb, 0, 'Reducing the augmented matrix to triangular (echelon) form and back-solving gives $x_3=-1$ from the last row, then $x_2=-1/5$ and $x_1=12/5$ from the equations above it, exactly the procedure demonstrated in Examples 3-5. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using Gaussian elimination, solve the system:\n$2x1 + x2 - x3 = 1$,\n$ x1 - x2 + 2x3 = 3$,\n$ 3x1 + 2x2 + x3 = 8$.', '["$x_1=3/5, x_2=2, x_3=11/5$", "$x_1=8/5, x_2=2, x_3=11/5$", "$x_1=3/5, x_2=1, x_3=16/5$", "$x_1=2, x_2=3/5, x_3=11/5$"]'::jsonb, 0, 'Reducing the augmented matrix to triangular (echelon) form and back-solving gives $x_3=11/5$ from the last row, then $x_2=2$ and $x_1=3/5$ from the equations above it, exactly the procedure demonstrated in Examples 3-5. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Using Gaussian elimination, solve the system:\n$x1 + x2 + x3 = 6$,\n$ 2x1 - x2 + x3 = 3$,\n$ x1 + 2x2 - x3 = 2$.', '["$x_1=1, x_2=2, x_3=3$", "$x_1=2, x_2=2, x_3=3$", "$x_1=1, x_2=1, x_3=4$", "$x_1=2, x_2=1, x_3=3$"]'::jsonb, 0, 'Reducing the augmented matrix to triangular (echelon) form and back-solving gives $x_3=3$ from the last row, then $x_2=2$ and $x_1=1$ from the equations above it, exactly the procedure demonstrated in Examples 3-5. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is the first step of the Gaussian Elimination Process described in the lecture notes, for a system where $x_1$ does not appear in the first equation?', '["Interchange the first equation with another so that $x_1$ appears in the first equation", "Delete the first equation entirely", "Solve the last equation first", "Multiply every equation by zero"]'::jsonb, 0, 'Step 1 of the notes'' Gaussian Elimination Process: "If necessary, interchange the first equation with another so that $x_1$ appears in the first equation." [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'After $x_1$ appears in the first equation, what is Step 2 of the Gaussian Elimination Process?', '["Eliminate $x_1$ from every equation but the first, by adding appropriate multiples of the first equation", "Solve for $x_1$ immediately", "Discard all equations except the first", "Interchange the last two equations"]'::jsonb, 0, 'Step 2: "Eliminate $x_1$ from every equation but the first by adding the appropriate multiples of the first equation" -- this is what produces the zeros beneath the leading entry of the first column. [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is the goal of Gaussian elimination, as stated in the lecture notes'' Remark?', '["To reduce the given system to an equivalent system in ''triangular'' form", "To increase the number of unknowns", "To make every coefficient equal to 1 before any other step", "To eliminate the constant terms entirely"]'::jsonb, 0, 'The Remark states: "The goal of Gaussian elimination is to reduce the given system of equation to an equivalent system in the ''triangular'' form." [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the system $x_1 - 2x_2 + x_3 = 2$, $2x_1 + x_2 - x_3 = 1$, $-3x_1 + x_2 - 2x_3 = -5$ (Example 5 of the notes), Gaussian elimination reduces it to the triangular system $x_1 - 2x_2 + x_3 = 2$, $5x_2 - 3x_3 = -3$, $-2x_3 = -2$. What is the unique solution?', '["$x_1 = 1, x_2 = 0, x_3 = 1$", "$x_1 = 2, x_2 = -3, x_3 = 1$", "$x_1 = 0, x_2 = 1, x_3 = 1$", "$x_1 = 1, x_2 = 1, x_3 = 0$"]'::jsonb, 0, 'Back-solving: $-2x_3=-2 \Rightarrow x_3=1$. Then $5x_2 - 3(1)=-3 \Rightarrow x_2=0$. Then $x_1 - 2(0) + 1 = 2 \Rightarrow x_1=1$. This exact result is worked out step by step in the notes'' own Example 5. [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'The system $x_1 - 2x_2 - x_3 = -2$, $2x_1 + x_2 + 3x_3 = 2$, $-3x_1 + x_2 - 2x_3 = 1.1$ reduces, after Gaussian elimination, to a row reading $0x_3 = 0.1$. What does this indicate about the system?', '["It has infinitely many solutions", "It is inconsistent (has no solution), since no value of $x_3$ satisfies $0 \\cdot x_3 = 0.1$", "It has exactly one solution, $x_3 = 0.1$", "It has exactly one solution, $x_3 = 10$"]'::jsonb, 1, 'No number multiplied by 0 can equal 0.1, so this row can never be satisfied -- exactly the reasoning given for Example 6 in the notes: "Because there is no number $x_3$ such that $0x_3 = 0.1$ system (12b) is inconsistent." [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Consider the $(2\times3)$ system $x_1 - x_3 = 1$, $x_2 + x_3 = -1$ from the lecture notes. Why does the notes say this system has infinitely many solutions rather than a unique one?', '["Because attempts to eliminate a further variable make no further progress -- $x_3$ is a free parameter, and specific solutions come from choosing a value for it", "Because the system was solved incorrectly", "Because both equations are identical", "Because the system has more equations than unknowns"]'::jsonb, 0, 'The notes explain that no further variable can be eliminated because "the system has infinitely many solutions, and at least one free parameter... is required in order to describe the solutions" -- here $x_3$ is free, giving $x_1 = 1+x_3$, $x_2 = -1-x_3$. [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Description of Solutions', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the system $x_1 - x_3 = 1$, $x_2 + x_3 = -1$ with $x_3$ as a free parameter ($x_1 = 1+x_3$, $x_2 = -1-x_3$), what is the solution when $x_3 = 1$?', '["$x_1 = 2, x_2 = -2, x_3 = 1$", "$x_1 = 1, x_2 = -1, x_3 = 1$", "$x_1 = 0, x_2 = 0, x_3 = 1$", "$x_1 = 2, x_2 = 2, x_3 = 1$"]'::jsonb, 0, 'Substituting $x_3=1$: $x_1 = 1+1=2$ and $x_2=-1-1=-2$ -- this exact solution is given in the notes as the example for $x_3=1$. [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Description of Solutions', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In ''back solving'' a reduced $(m\times n)$ system where the diagonal coefficients $c_{11}, c_{22}, \ldots, c_{mm}$ are all non-zero, which variables are treated as ''free parameters''?', '["$x_{m+1}, \\ldots, x_n$ (the variables beyond the $m$th)", "$x_1$ only", "All variables are free", "None; there are never free parameters in back solving"]'::jsonb, 0, 'The notes state: "if we allow $x_{m+1}, \ldots, x_n$ being free parameters then $x_m$ is determined from the last equation" -- and each earlier $x_i$ is then expressed in terms of those same free parameters working backward. [Source: Ch.1, pp.5-9 (“Description of the Set of Solutions”, “Back Solving”)]', 'Description of Solutions', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In an $(m\times n)$ matrix, what do $m$ and $n$ represent?', '["$m$ rows and $n$ columns", "$m$ columns and $n$ rows", "$m$ is always equal to $n$", "$m$ is the determinant and $n$ is the trace"]'::jsonb, 0, 'The notes state plainly: "an $(m\times n)$ matrix has $m$ rows and $n$ columns." [Source: Ch.1, pp.9-12 (“Matrices”, “Augmented Matrix”)]', 'Matrices', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'In the notation $A = (a_{ij})$ for a matrix, what does the entry $a_{32}$ represent?', '["The entry in the third row and second column of $A$", "The entry in the second row and third column of $A$", "The determinant of a $3\\times2$ submatrix", "The sum of row 3 and column 2"]'::jsonb, 0, 'As with the coefficient notation for systems, $a_{32}$ "is the entry in the third row and second column of A" -- row subscript first, column subscript second. [Source: Ch.1, pp.9-12 (“Matrices”, “Augmented Matrix”)]', 'Matrices', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'What is the ''augmented matrix'' for a system of linear equations $A\mathbf{x} = \mathbf{b}$?', '["The matrix $A$ with the column vector $b$ attached as an extra column, often written $[A|b]$", "The matrix $A$ multiplied by itself", "Only the vector $b$ written as a matrix", "The transpose of $A$"]'::jsonb, 0, 'The notes define the augmented matrix as the $(m\times n+1)$ matrix formed by the coefficients together with the constants column, "usually denoted by $[A/b]$ where A is the coefficient matrix... and b" is the constants vector. [Source: Ch.1, pp.9-12 (“Matrices”, “Augmented Matrix”)]', 'Matrices', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the system $x_1 - 2x_2 + x_3 = 2$, $2x_1 + x_2 - x_3 = 1$, $-3x_1 + x_2 - 2x_3 = -5$, what is the coefficient matrix $A$?', '["$\\begin{pmatrix}1 & -2 & 1\\\\ 2 & 1 & -1\\\\ -3 & 1 & -2\\end{pmatrix}$", "$\\begin{pmatrix}1 & -2 & 1 & 2\\\\ 2 & 1 & -1 & 1\\\\ -3 & 1 & -2 & -5\\end{pmatrix}$", "$\\begin{pmatrix}2\\\\ 1\\\\ -5\\end{pmatrix}$", "$\\begin{pmatrix}1 & 2 & -3\\\\ -2 & 1 & 1\\\\ 1 & -1 & -2\\end{pmatrix}$"]'::jsonb, 0, 'The coefficient matrix $A$ contains only the coefficients of $x_1, x_2, x_3$ from each equation, row by row -- the second option is actually the full augmented matrix $[A|b]$ (it includes the constants column too), and the fourth is $A$''s transpose. [Source: Ch.1, pp.9-12 (“Matrices”, “Augmented Matrix”)]', 'Matrices', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Gaussian elimination to solve the system:\n$x_1+3x_2-4x_3 = -14$,\n$4x_1-x_2-x_3 = 13$,\n$3x_2-x_3 = -11$.', '["$x_1=3, x_2=-3, x_3=2$", "$x_1=5, x_2=-3, x_3=2$", "$x_1=3, x_2=-3, x_3=0$", "$x_1=-3, x_2=3, x_3=2$"]'::jsonb, 0, 'Reducing the system by elementary row operations (as in the notes'' Examples 3-5) and back-solving from the resulting triangular form gives $x_1=3$, $x_2=-3$, $x_3=2$. Substituting confirms all three original equations hold. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Gaussian elimination to solve the system:\n$-x_2-2x_3 = 9$,\n$-3x_1+3x_2+4x_3 = -14$,\n$x_1-x_2+3x_3 = -17$.', '["$x_1=-1, x_2=1, x_3=-5$", "$x_1=1, x_2=1, x_3=-5$", "$x_1=-1, x_2=1, x_3=-7$", "$x_1=1, x_2=-1, x_3=-5$"]'::jsonb, 0, 'Reducing the system by elementary row operations (as in the notes'' Examples 3-5) and back-solving from the resulting triangular form gives $x_1=-1$, $x_2=1$, $x_3=-5$. Substituting confirms all three original equations hold. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Gaussian elimination to solve the system:\n$2x_1+2x_2-x_3 = 13$,\n$-3x_1+2x_2+3x_3 = -29$,\n$-x_2-3x_3 = 10$.', '["$x_1=6, x_2=-1, x_3=-3$", "$x_1=8, x_2=-1, x_3=-3$", "$x_1=6, x_2=-1, x_3=-5$", "$x_1=-1, x_2=6, x_3=-3$"]'::jsonb, 0, 'Reducing the system by elementary row operations (as in the notes'' Examples 3-5) and back-solving from the resulting triangular form gives $x_1=6$, $x_2=-1$, $x_3=-3$. Substituting confirms all three original equations hold. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Gaussian elimination to solve the system:\n$x_1+2x_3 = 12$,\n$2x_1-x_2+2x_3 = 13$,\n$-3x_1+2x_2+2x_3 = 2$.', '["$x_1=4, x_2=3, x_3=4$", "$x_1=6, x_2=3, x_3=4$", "$x_1=4, x_2=3, x_3=2$", "$x_1=3, x_2=4, x_3=4$"]'::jsonb, 0, 'Reducing the system by elementary row operations (as in the notes'' Examples 3-5) and back-solving from the resulting triangular form gives $x_1=4$, $x_2=3$, $x_3=4$. Substituting confirms all three original equations hold. [Source: Ch.1, pp.3-4 (“Reduction Process” / “Gaussian Elimination”, Examples 2-4)]', 'Gaussian Elimination', false, 'second', 2),
