  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=16$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$16$", "$-16$", "$17$", "$15$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 16$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=0$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$0$", "$5$", "$1$", "$-1$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 0$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}-1 & 0 & -1\\ -5 & 5 & 0\\ -5 & 0 & 2\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$10$", "$13$", "$-10$", "$8$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}5 & 0\\ 0 & 2\end{pmatrix}$, whose determinant is $M_{11}=10$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
