  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}6 & -5 & 1\\ -3 & 2 & 6\\ -6 & 2 & -3\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$-18$", "$-15$", "$18$", "$-20$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}2 & 6\\ 2 & -3\end{pmatrix}$, whose determinant is $M_{11}=-18$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=-18$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$-18$", "$18$", "$-17$", "$-19$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = -18$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}-4 & 4 & 0\\ 0 & 3 & 4\\ -1 & 5 & 6\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$-2$", "$1$", "$2$", "$-4$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}3 & 4\\ 5 & 6\end{pmatrix}$, whose determinant is $M_{11}=-2$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=-2$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$-2$", "$2$", "$-1$", "$-3$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = -2$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}5 & -4 & 4\\ 0 & 3 & -6\\ -5 & -4 & 2\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$-18$", "$-15$", "$18$", "$-20$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}3 & -6\\ -4 & 2\end{pmatrix}$, whose determinant is $M_{11}=-18$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=-18$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$-18$", "$18$", "$-17$", "$-19$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = -18$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}0 & -5 & -1\\ -1 & -5 & -1\\ -5 & 6 & -6\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$36$", "$39$", "$-36$", "$34$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}-5 & -1\\ 6 & -6\end{pmatrix}$, whose determinant is $M_{11}=36$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=36$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$36$", "$-36$", "$37$", "$35$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 36$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}-1 & 6 & -2\\ -3 & -1 & -1\\ -3 & 1 & -3\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$4$", "$7$", "$-4$", "$2$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}-1 & -1\\ 1 & -3\end{pmatrix}$, whose determinant is $M_{11}=4$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=4$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$4$", "$-4$", "$5$", "$3$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 4$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}-1 & -5 & 4\\ 1 & 4 & 3\\ 1 & 2 & -6\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$-30$", "$-27$", "$30$", "$-32$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}4 & 3\\ 2 & -6\end{pmatrix}$, whose determinant is $M_{11}=-30$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=-30$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$-30$", "$30$", "$-29$", "$-31$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = -30$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the matrix $A = \begin{pmatrix}-6 & -6 & -6\\ 1 & -4 & 5\\ -6 & 3 & -6\end{pmatrix}$, what is the minor $M_{11}$ (delete row 1 and column 1, then take the determinant)?', '["$9$", "$12$", "$-9$", "$7$"]'::jsonb, 0, 'Deleting row 1 and column 1 leaves $\begin{pmatrix}-4 & 5\\ 3 & -6\end{pmatrix}$, whose determinant is $M_{11}=9$ -- exactly the minor-matrix procedure in the notes'' Definition. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For the same matrix $A$ (minor $M_{11}=9$), what is the cofactor $A_{11} = (-1)^{1+1}\det(M_{11})$?', '["$9$", "$-9$", "$10$", "$8$"]'::jsonb, 0, 'Since $(-1)^{1+1}=1$, the cofactor $A_{11}$ equals the minor itself: $A_{11} = 9$. [Source: Ch.1, pp.14-16 (“Determinants”, cofactors/minors, Examples 1-5)]', 'Cofactors and Minors', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & 2\\ -1 & 3\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$-3$", "$-1$", "$3$", "$-4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=3$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 3/-1 = -3$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & -5\\ 0 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & 6\\ 1 & -5\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$5$", "$7$", "$-5$", "$4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-5$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -5/-1 = 5$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-5 & -1\\ 6 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 0\\ 1 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 0\\ 6 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 5\\ -1 & -6\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$6$", "$8$", "$-6$", "$5$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-6$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -6/-1 = 6$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 1\\ -3 & -4\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$4$", "$6$", "$-4$", "$3$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-4$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -4/-1 = 4$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & -5\\ 1 & 3\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$-3$", "$-1$", "$3$", "$-4$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=3$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 3/-1 = -3$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}5 & -2\\ 2 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}4 & 3\\ -1 & -1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -1/-1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & 1\\ 1 & -4\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$4$", "$6$", "$-4$", "$3$"]'::jsonb, 0, '$\det(A) = -1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=-4$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = -4/-1 = 4$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}1 & 1\\ 0 & 1\end{pmatrix}$, use the adjoint formula $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$ to find the $(1,1)$ entry of $A^{-1}$.', '["$1$", "$3$", "$-1$", "$0$"]'::jsonb, 0, '$\det(A) = 1$. The adjoint''s $(1,1)$ entry is the cofactor $A_{22}=1$ (for a $2\times2$ matrix the adjoint swaps the diagonal and negates the off-diagonal), so $(A^{-1})_{11} = 1/1 = 1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & 0 & -1\\ 1 & 1 & 1\\ -2 & 3 & 1\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$4$", "$7$", "$-4$", "$2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 4$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}3 & -4 & 3\\ -2 & 1 & -4\\ 2 & -2 & 3\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-3$", "$0$", "$3$", "$-5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -3$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & -4 & -1\\ 1 & -2 & -1\\ -4 & 3 & 3\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-4$", "$-1$", "$4$", "$-6$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -4$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-1 & -3 & 3\\ -4 & 3 & -1\\ 3 & 1 & -2\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$7$", "$10$", "$-7$", "$5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 7$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 2 & 1\\ 1 & -1 & -2\\ 2 & 3 & 2\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$2$", "$5$", "$-2$", "$0$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 2$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 1 & 4\\ 1 & 1 & 1\\ 1 & 1 & 2\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$0$", "$3$", "$6$", "$-2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 0$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 3 & -3\\ -1 & -1 & 1\\ 0 & -1 & 0\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$0$", "$3$", "$6$", "$-2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 0$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & 0 & -3\\ 1 & -4 & 4\\ 4 & 3 & 4\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-4$", "$-1$", "$4$", "$-6$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -4$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-2 & -1 & 1\\ 0 & 2 & -1\\ 3 & -2 & 0\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-3$", "$0$", "$3$", "$-5$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -3$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}0 & 1 & -4\\ -1 & -1 & 3\\ -2 & 0 & -1\end{pmatrix}$, given that $\det(A) = 1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-8$", "$-5$", "$8$", "$-10$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -8$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}2 & 4 & -3\\ 0 & -3 & -1\\ 1 & 3 & -1\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$-1$", "$2$", "$1$", "$-3$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = -1$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'For $A = \begin{pmatrix}-3 & 0 & -2\\ -4 & 2 & -3\\ 3 & 1 & 2\end{pmatrix}$, given that $\det(A) = -1$, find the $(2,2)$ entry of $A^{-1}$ using $A^{-1} = \frac{1}{\det(A)}\operatorname{adj}(A)$.', '["$0$", "$3$", "$6$", "$-2$"]'::jsonb, 0, 'The $(2,2)$ entry of $A^{-1}$ is the cofactor $A_{22}$ divided by $\det(A)=-1$. Computing the $2\times2$ minor obtained by deleting row 2 and column 2 and applying the sign $(-1)^{2+2}=1$ gives $(A^{-1})_{22} = 0$. [Source: Ch.1, pp.21-22 (“Inverses of Matrix”, Adjoint)]', 'Inverse of a Matrix', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): x_1-x_2+x_3 = 10, \;x_1+4x_2+x_3 = 0, \;-2x_1+x_2+x_3 = -6.', '["$(x_1,x_2,x_3) = (4, -2, 4)$", "$(x_1,x_2,x_3) = (5, -2, 4)$", "$(x_1,x_2,x_3) = (4, -3, 4)$", "$(x_1,x_2,x_3) = (4, -2, 5)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=4, x_2=-2, x_3=4$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): -4x_1+x_2+3x_3 = 4, \;-4x_1+x_2-x_3 = 0, \;-2x_1+3x_2-4x_3 = 9.', '["$(x_1,x_2,x_3) = (1, 5, 1)$", "$(x_1,x_2,x_3) = (2, 5, 1)$", "$(x_1,x_2,x_3) = (1, 4, 1)$", "$(x_1,x_2,x_3) = (1, 5, 2)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=1, x_2=5, x_3=1$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): -4x_1-x_2-4x_3 = 14, \;x_1+2x_2+3x_3 = -15, \;-2x_1+2x_2+2x_3 = -14.', '["$(x_1,x_2,x_3) = (1, -2, -4)$", "$(x_1,x_2,x_3) = (2, -2, -4)$", "$(x_1,x_2,x_3) = (1, -3, -4)$", "$(x_1,x_2,x_3) = (1, -2, -3)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=1, x_2=-2, x_3=-4$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): 3x_1+4x_2+2x_3 = 1, \;-2x_1-3x_2-x_3 = 2, \;4x_1-x_2+2x_3 = 31.', '["$(x_1,x_2,x_3) = (5, -5, 3)$", "$(x_1,x_2,x_3) = (6, -5, 3)$", "$(x_1,x_2,x_3) = (5, -6, 3)$", "$(x_1,x_2,x_3) = (5, -5, 4)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=5, x_2=-5, x_3=3$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): x_1+x_2+3x_3 = -23, \;-4x_3 = 20, \;-4x_1+x_2+3x_3 = 7.', '["$(x_1,x_2,x_3) = (-6, -2, -5)$", "$(x_1,x_2,x_3) = (-5, -2, -5)$", "$(x_1,x_2,x_3) = (-6, -3, -5)$", "$(x_1,x_2,x_3) = (-6, -2, -4)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=-6, x_2=-2, x_3=-5$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): -x_1+2x_2-3x_3 = -31, \;4x_1-4x_3 = -20, \;-x_2+4x_3 = 30.', '["$(x_1,x_2,x_3) = (1, -6, 6)$", "$(x_1,x_2,x_3) = (2, -6, 6)$", "$(x_1,x_2,x_3) = (1, -7, 6)$", "$(x_1,x_2,x_3) = (1, -6, 7)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=1, x_2=-6, x_3=6$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): -3x_1-4x_2-2x_3 = -16, \;x_1+x_2 = 7, \;2x_1+4x_2-3x_3 = 39.', '["$(x_1,x_2,x_3) = (2, 5, -5)$", "$(x_1,x_2,x_3) = (3, 5, -5)$", "$(x_1,x_2,x_3) = (2, 4, -5)$", "$(x_1,x_2,x_3) = (2, 5, -4)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=2, x_2=5, x_3=-5$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): 4x_1-x_2 = -10, \;-4x_1+2x_2-3x_3 = -2, \;3x_1-x_2-2x_3 = -10.', '["$(x_1,x_2,x_3) = (-4, -6, 2)$", "$(x_1,x_2,x_3) = (-3, -6, 2)$", "$(x_1,x_2,x_3) = (-4, -7, 2)$", "$(x_1,x_2,x_3) = (-4, -6, 3)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=-4, x_2=-6, x_3=2$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
