  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): -4x_1+2x_2+3x_3 = 17, \;-4x_1+2x_2-2x_3 = -8, \;x_1+x_2+4x_3 = 27.', '["$(x_1,x_2,x_3) = (2, 5, 5)$", "$(x_1,x_2,x_3) = (3, 5, 5)$", "$(x_1,x_2,x_3) = (2, 4, 5)$", "$(x_1,x_2,x_3) = (2, 5, 6)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=2, x_2=5, x_3=5$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): 3x_1+4x_2+2x_3 = -44, \;x_1+2x_2+3x_3 = -32, \;-2x_1-3x_2+3x_3 = 5.', '["$(x_1,x_2,x_3) = (-4, -5, -6)$", "$(x_1,x_2,x_3) = (-3, -5, -6)$", "$(x_1,x_2,x_3) = (-4, -6, -6)$", "$(x_1,x_2,x_3) = (-4, -5, -5)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=-4, x_2=-5, x_3=-6$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): 4x_1-3x_2+3x_3 = 29, \;-2x_1+2x_2-3x_3 = -22, \;-2x_1+4x_2-4x_3 = -32.', '["$(x_1,x_2,x_3) = (2, -3, 4)$", "$(x_1,x_2,x_3) = (3, -3, 4)$", "$(x_1,x_2,x_3) = (2, -4, 4)$", "$(x_1,x_2,x_3) = (2, -3, 5)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=2, x_2=-3, x_3=4$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Solve the system by Gaussian elimination (reduction to row-echelon form): 4x_1-3x_2 = 42, \;-4x_1-4x_2-4x_3 = -20, \;-3x_1+3x_2+3x_3 = -21.', '["$(x_1,x_2,x_3) = (6, -6, 5)$", "$(x_1,x_2,x_3) = (7, -6, 5)$", "$(x_1,x_2,x_3) = (6, -7, 5)$", "$(x_1,x_2,x_3) = (6, -6, 6)$"]'::jsonb, 0, 'Eliminating variables systematically (as in the notes'' Reduction Process) yields $x_1=6, x_2=-6, x_3=5$, verified by back-substitution into all three equations. [Source: Ch.1, pp.3-6 (“Reduction Process” / “Gaussian Elimination”)]', 'Gaussian Elimination', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Cramer''s Rule to solve: -4x_1+4x_2 = -20, \;-x_1+5x_2 = 7. (Given $D = -16$.)', '["$(x_1,x_2) = (8, 3)$", "$(x_1,x_2) = (9, 3)$", "$(x_1,x_2) = (8, 4)$", "$(x_1,x_2) = (-8, 3)$"]'::jsonb, 0, '$D_1 = -128$, $D_2 = -48$, so $x_1 = D_1/D = -128/-16 = 8$ and $x_2 = D_2/D = -48/-16 = 3$. [Source: Ch.1, pp.7-9 (“Cramer''s Rule”)]', 'Cramer''s Rule', false, 'second', 2),
  ('mth-208-numerical-analysis', 'MTH 208: Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences, Faculty of Engineering', 'Mathematics', '200 Level', 'Use Cramer''s Rule to solve: 5x_1-6x_2 = -45, \;4x_1 = -12. (Given $D = 24$.)', '["$(x_1,x_2) = (-3, 5)$", "$(x_1,x_2) = (-2, 5)$", "$(x_1,x_2) = (-3, 6)$", "$(x_1,x_2) = (3, 5)$"]'::jsonb, 0, '$D_1 = -72$, $D_2 = 120$, so $x_1 = D_1/D = -72/24 = -3$ and $x_2 = D_2/D = 120/24 = 5$. [Source: Ch.1, pp.7-9 (“Cramer''s Rule”)]', 'Cramer''s Rule', false, 'second', 2),
